query loggedInAccount {
  loggedInAccount {
    id
    name
    slug
  }
}

query account($slug: String) {
  account(slug: $slug) {
    id
    name
    slug
  }
}

{
  "slug": "znarf"
}

query account($slug: String) {
  account(slug: $slug) {
    name
    slug
    memberOf(role: BACKER) {
      totalCount
      nodes {
        account {
          name
          slug
        }
      }
    }
  }
}

{
  "slug": "znarf"
}

query account($slug: String) {
  account(slug: $slug) {
    name
    slug
    members(role: BACKER, limit: 100) {
      totalCount
      nodes {
        account {
          name
          slug
        }
      }
    }
  }
}

{
  "slug": "babel"
}

query account($slug: String) {
  account(slug: $slug) {
    name
    slug
    transactions(limit: 10, type: CREDIT) {
      totalCount
      nodes {
        type
        fromAccount {
          name
          slug
        }
        amount {
          value
          currency
        }
        createdAt
      }
    }
  }
}

{
  "slug": "babel"
}

query account($slug: String) {
  account(slug: $slug) {
    name
    slug
    transactions(limit: 10, type: DEBIT) {
      totalCount
      nodes {
        type
        toAccount {
          name
          slug
        }
        amount {
          value
          currency
        }
        createdAt
      }
    }
  }
}

{
  "slug": "babel"
